package test;

import org.eclipse.jdt.ui.JavaUI;

public class EditorConfig {
    public void configureEditor(String id) {
        boolean isModuleInfo = false;
        // Old code referencing the generic ID for class files without source
        if (JavaUI.ID_MODULE_INFO_EDITOR.equals(id) || JavaUI.ID_MODULE_INFO_CF_EDITOR.equals(id) || JavaUI.ID_CF_EDITOR_NO_SOURCE.equals(id)) {
            isModuleInfo = true;
        }
        System.out.println("Is module info: " + isModuleInfo);
    }
}

